"""All Cypher is generated by the backend, never by browser or model input."""
import os
from importlib.util import find_spec


class ConfigurationError(RuntimeError):
    pass


class DatabaseOperationError(RuntimeError):
    pass


class GraphSchemaError(DatabaseOperationError):
    pass


class DuplicateTitleError(ValueError):
    pass


REQUIRED_CONSTRAINTS = (
    ("lfe_case_id", "LFECase", "id"),
    ("lfe_case_title_key", "LFECase", "title_key"),
    ("lfe_project_identity", "Project", "identity_key"),
    ("lfe_product_identity", "Product", "identity_key"),
    ("lfe_line_identity", "ProductionLine", "identity_key"),
    ("lfe_machine_identity", "Machine", "identity_key"),
    ("lfe_component_identity", "MachineComponent", "identity_key"),
    ("lfe_material_identity", "Material", "identity_key"),
    ("lfe_supplier_identity", "Supplier", "identity_key"),
)
REQUIRED_RELATIONSHIP_CONSTRAINTS = (
    ("lfe_component_link_identity", "HAS_COMPONENT", "identity_key"),
)


class Neo4jRepository:
    def __init__(self, env=None):
        env = os.environ if env is None else env
        self.uri = env.get("NEO4J_URI", "").strip()
        self.username = env.get("NEO4J_USERNAME", "").strip()
        self.password = env.get("NEO4J_PASSWORD", "")
        self.database = env.get("NEO4J_DATABASE", "").strip() or "neo4j"

    def validate_configuration(self):
        if not all((self.uri, self.username, self.password, self.database)):
            raise ConfigurationError("Neo4j is not configured. Set URI, username, password and database locally.")
        if not self.uri.startswith(("neo4j+s://", "neo4j+ssc://", "bolt+s://", "bolt+ssc://", "bolt://", "neo4j://")):
            raise ConfigurationError("Unsupported Neo4j URI scheme.")

    def status(self):
        try:
            self.validate_configuration()
        except ConfigurationError as exc:
            return {"configured": False, "message": str(exc)}
        if find_spec("neo4j") is None:
            return {"configured": False, "message": "Neo4j driver is missing. Install the project requirements."}
        return {"configured": True, "message": "Configured; connection not checked. Select Check connection."}

    def driver(self):
        self.validate_configuration()
        try:
            from neo4j import GraphDatabase
        except ImportError as exc:
            raise ConfigurationError("Neo4j driver is missing. Install the project requirements.") from exc
        try:
            return GraphDatabase.driver(self.uri, auth=(self.username, self.password))
        except Exception as exc:
            raise DatabaseOperationError("Neo4j connection failed. Check the local URI, credentials, and database availability.") from exc

    def check_connection(self):
        try:
            with self.driver() as driver:
                driver.verify_connectivity()
                with driver.session(database=self.database, default_access_mode="READ") as session:
                    value = session.execute_read(lambda tx: tx.run("RETURN 1 AS ok").single()["ok"])
                    if value != 1:
                        raise DatabaseOperationError("Neo4j connection check returned an unexpected result.")
        except ConfigurationError:
            raise
        except Exception as exc:
            raise DatabaseOperationError("Neo4j connection check failed. Check the local URI, credentials, database name, and availability.") from exc
        return {"connected": True, "message": "Connected. A read-only database check succeeded."}

    def write(self, graph):
        try:
            with self.driver() as driver:
                with driver.session(database=self.database) as session:
                    session.execute_write(self._write_transaction, graph)
        except (ConfigurationError, DuplicateTitleError, DatabaseOperationError):
            raise
        except Exception as exc:
            from neo4j.exceptions import ConstraintError
            if isinstance(exc, ConstraintError):
                try:
                    with self.driver() as driver:
                        with driver.session(database=self.database, default_access_mode="READ") as session:
                            duplicate = session.execute_read(self._duplicate_title, graph["case"])
                    if duplicate:
                        raise DuplicateTitleError("Another LFE case already has this title. Change the title and submit it for approval again.") from exc
                except DuplicateTitleError:
                    raise
                except Exception:
                    pass
                raise DatabaseOperationError("Neo4j rejected a uniqueness constraint. Check the graph schema and existing data.") from exc
            raise DatabaseOperationError("Neo4j write failed. Check the connection, database name, and write permissions.") from exc

    def create_constraints(self):
        try:
            with self.driver() as driver:
                with driver.session(database=self.database) as session:
                    for name, label, prop in REQUIRED_CONSTRAINTS:
                        session.run(f"CREATE CONSTRAINT {name} IF NOT EXISTS "
                                    f"FOR (n:{label}) REQUIRE n.{prop} IS UNIQUE").consume()
                    for name, relation, prop in REQUIRED_RELATIONSHIP_CONSTRAINTS:
                        session.run(f"CREATE CONSTRAINT {name} IF NOT EXISTS "
                                    f"FOR ()-[r:{relation}]-() REQUIRE r.{prop} IS UNIQUE").consume()
                    session.execute_read(self._require_constraints)
        except ConfigurationError:
            raise
        except Exception as exc:
            raise DatabaseOperationError("Could not install or verify Neo4j uniqueness constraints. Check schema permissions and existing data.") from exc

    @staticmethod
    def _require_constraints(tx):
        result = tx.run("SHOW CONSTRAINTS YIELD type, entityType, labelsOrTypes, properties "
                        "RETURN type, entityType, labelsOrTypes, properties")
        found = {(row["entityType"], tuple(row["labelsOrTypes"]), tuple(row["properties"])) for row in result
                 if row["type"] in ("NODE_PROPERTY_UNIQUENESS", "RELATIONSHIP_PROPERTY_UNIQUENESS",
                                    "UNIQUENESS", "NODE_KEY", "RELATIONSHIP_KEY")}
        expected = ([("NODE", (label,), (prop,)) for _, label, prop in REQUIRED_CONSTRAINTS] +
                    [("RELATIONSHIP", (relation,), (prop,)) for _, relation, prop in REQUIRED_RELATIONSHIP_CONSTRAINTS])
        if any(constraint not in found for constraint in expected):
            raise GraphSchemaError("Required Neo4j uniqueness constraints are missing. Install the LFE graph constraints before uploading.")
        legacy = tx.run("MATCH (c:LFECase) WHERE c.id IS NULL OR c.title_key IS NULL "
                        "RETURN count(c) AS count").single()
        if legacy["count"]:
            raise GraphSchemaError("Existing LFE cases are missing identity keys. Migrate or review them before uploading.")

    @staticmethod
    def _duplicate_title(tx, case):
        return tx.run("MATCH (c:LFECase {title_key: $title_key}) WHERE c.id <> $id "
                      "RETURN c.id AS id LIMIT 1", title_key=case["title_key"], id=case["id"]).single() is not None

    @staticmethod
    def _write_transaction(tx, graph):
        case = graph["case"]
        Neo4jRepository._require_constraints(tx)
        legacy = tx.run("MATCH (c:LFECase) WHERE coalesce(c.graph_schema_version, 1) <> $version "
                        "RETURN count(c) AS count", version=case["graph_schema_version"]).single()
        if legacy["count"]:
            raise GraphSchemaError("Existing cases use an earlier graph mapping. Review and migrate them before uploading.")
        if Neo4jRepository._duplicate_title(tx, case):
            raise DuplicateTitleError("Another LFE case already has this title. Change the title and submit it for approval again.")
        tx.run("MERGE (c:LFECase {id: $id}) SET c += $props", id=case["id"], props=case).consume()
        allowed = {
            "Project": "HAS_PROJECT", "Product": "HAS_PRODUCT",
            "ProductionLine": "HAS_LINE", "Machine": "HAS_MACHINE",
            "MachineComponent": "HAS_COMPONENT", "Material": "HAS_MATERIAL",
            "Supplier": "HAS_SUPPLIER", "Issue": "HAS_ISSUE", "Defect": "HAS_DEFECT",
            "ConfirmedCause": "HAS_CAUSE", "SafetyImpact": "HAS_SAFETY_IMPACT",
            "QualityImpact": "HAS_QUALITY_IMPACT", "CapacityImpact": "HAS_CAPACITY_IMPACT",
            "Action": "HAS_ACTION", "Verification": "HAS_VERIFICATION", "Evidence": "HAS_EVIDENCE",
        }
        for index, node in enumerate(graph["nodes"]):
            label, relation = node["label"], node["relation"]
            if allowed.get(label) != relation:
                raise ValueError("Invalid graph mapping.")
            link_key = f"case:{case['id']}:{index}" if label == "MachineComponent" else None
            case_relation = (f"[r:{relation} {{identity_key: $link_key}}]" if link_key
                             else f"[r:{relation}]")
            if "identity_key" in node:
                if label not in ("Project", "Product", "ProductionLine", "Machine", "MachineComponent", "Material", "Supplier"):
                    raise ValueError("Invalid shared graph mapping.")
                query = (f"MATCH (c:LFECase {{id: $id}}) "
                         f"MERGE (n:{label} {{identity_key: $identity_key}}) "
                         f"ON CREATE SET n += $props "
                         f"MERGE (c)-{case_relation}->(n) SET r += $relation_props")
                tx.run(query, id=case["id"], identity_key=node["identity_key"], props=node["properties"],
                       relation_props=node.get("relationship_properties", {}), link_key=link_key).consume()
            else:
                query = (f"MATCH (c:LFECase {{id: $id}}) "
                         f"MERGE (n:{label} {{case_id: $id, item: $item}}) "
                         f"SET n += $props MERGE (c)-{case_relation}->(n)")
                tx.run(query, id=case["id"], item=index, props=node["properties"], link_key=link_key).consume()
            if label == "MachineComponent" and "machine_ref" in node:
                machine_ref = node["machine_ref"]
                machine_match = "{identity_key: $machine_key}" if "identity_key" in machine_ref else "{case_id: $id, item: $machine_item}"
                component_match = "{identity_key: $component_key}" if "identity_key" in node else "{case_id: $id, item: $item}"
                query = (f"MATCH (c:LFECase {{id: $id}})-[:HAS_MACHINE]->(m:Machine {machine_match}) "
                         f"MATCH (c)-[:HAS_COMPONENT]->(n:MachineComponent {component_match}) "
                         "MERGE (m)-[:HAS_COMPONENT {identity_key: $edge_key}]->(n)")
                params = {"id": case["id"],
                          "edge_key": ("shared:" + node["identity_key"]) if "identity_key" in node
                          else f"machine:{case['id']}:{index}"}
                if "identity_key" in machine_ref:
                    params["machine_key"] = machine_ref["identity_key"]
                else:
                    params["machine_item"] = machine_ref["item"]
                if "identity_key" in node:
                    params["component_key"] = node["identity_key"]
                else:
                    params["item"] = index
                tx.run(query, **params).consume()

    def search(self, question):
        if not isinstance(question, str) or not question.strip():
            raise ValueError("Enter a question.")
        # A fixed read-only query: no generated or user-provided Cypher is executed.
        try:
            with self.driver() as driver:
                with driver.session(database=self.database, default_access_mode="READ") as session:
                    return session.execute_read(self._search_transaction, question.strip())
        except ConfigurationError:
            raise
        except Exception as exc:
            raise DatabaseOperationError("Neo4j search failed. Check the connection, database name, and read permissions.") from exc

    @staticmethod
    def _search_transaction(tx, question):
        result = tx.run(
            "MATCH (c:LFECase) WHERE any(term IN $terms WHERE "
            "toLower(coalesce(c.title,'') + ' ' + coalesce(c.activity,'') + ' ' + "
            "coalesce(c.cause,'') + ' ' + coalesce(c.action,'') + ' ' + "
            "coalesce(c.defect_description,'') + ' ' + coalesce(c.project,'') + ' ' + "
            "coalesce(c.product,'') + ' ' + coalesce(c.material,'') + ' ' + "
            "coalesce(c.supplier,'') + ' ' + coalesce(c.machine,'') + ' ' + "
            "coalesce(c.line,'')) CONTAINS term) "
            "RETURN c.id AS id, c.title AS title, c.activity AS activity LIMIT 20",
            terms=[word.lower() for word in question.split() if len(word) > 1][:20],
        )
        return [dict(record) for record in result if record["id"]]
